pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // set up owner
        address owner = address(this);
        vm.deal(owner, 1 ether);
        vm.prank(owner);
        // call sendMoney which triggers receive on itself? Actually sendMoney calls external call.
        // We'll send to a dummy address that does nothing, but depositsCount increments on receive?
        // No: receive is only called when Ether is sent to C. sendMoney sends from C to _target.
        // The difference mentions that after sendMoney completes, depositsCount differs.
        // Actually the mutant only changes receive(), which is triggered when C receives Ether.
        // So we need to make C receive Ether to affect depositsCount.
        // The difference says driven through sendMoney, P and M differ in depositsCount after sendMoney.
        // sendMoney sends value to _target; that does not affect depositsCount directly.
        // But perhaps the test intends: call sendMoney with data that makes _target call back into C's receive?
        // Let's reinterpret: the bug statement says "Driven through sendMoney, P and M differ: after sendMoney completes, depositsCount differs."
        // This suggests that sendMoney can trigger receive on C via reentrancy.
        // We'll deploy a helper contract that on receive calls back to C's receive? No, receive is automatically called when sending Ether to C.
        // To trigger receive, we need to send Ether to C. sendMoney sends Ether from C to _target, not to C.
        // The only way sendMoney changes depositsCount is if _target is C itself? But then C sends Ether to itself, which triggers no receive because the call is from C to itself.
        // Alternatively, maybe the intention is to call sendMoney with _data that makes _target call back into C with value, causing receive.
        // Let's design a simple scenario: we have an attacker contract that when called by sendMoney, sends Ether back to C.
        // But we cannot define another contract. So we need a simpler approach: use the fact that sendMoney can send to a pre-existing address that has fallback that sends back.
        // Since no other contract allowed, we'll use address(0) or an EOA that reverts? That won't trigger receive on C.
        // Wait: the difference statement probably means that simply calling sendMoney does something that changes depositsCount differently between P and M.
        // But the mutant only changes receive logic, so the only way sendMoney affects depositsCount is if the _target's execution somehow triggers C's receive.
        // A known pattern: the owner (msg.sender) could be C itself? No, sendMoney is onlyOwner.
        // Let's read the original: sendMoney calls _target.call{value: _value}(_data). If _target is C again, and the data is empty, the fallback maybe? But C has no fallback, only receive, and receive is triggered when sending Ether with no data. But C sending to itself via call does not trigger receive because the call is to itself? Actually it does: self-call does trigger receive if value > 0 and data empty? Yes, in EVM, if you call a contract with value and empty calldata, the fallback or receive is triggered. So if we set _target = address(c), then c.sendMoney(address(c), value, "") will call C's receive, increasing depositsCount. That's the intended path.
        // So let owner call sendMoney with _target = address(c) and _value = 1 wei, _data = "".
        vm.prank(owner);
        c.sendMoney(address(c), 1 wei, "");
        // After this, depositsCount should be 1 in reference, but 2 in mutant.
        assertTrue(c.depositsCount() == 1);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Send 1 wei directly to c, triggering receive()
        vm.deal(address(this), 1 wei);
        vm.prank(address(this));
        (bool success, ) = address(c).call{value: 1 wei}("");
        require(success, "call failed");

        // In reference (P), depositsCount becomes 1; in mutant (M), it becomes 2
        assertTrue(c.depositsCount() == 1, "depositsCount should be 1");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Arrange: give the contract 1 wei via a direct deposit to trigger depositsCount
        // First send 1 wei to the contract to trigger receive (and increment depositsCount in reference)
        vm.deal(address(this), 1 ether);
        (bool success, ) = address(c).call{value: 1 wei}("");
        require(success, "initial deposit failed");
        // After this, reference has depositsCount = 1, buggy has depositsCount = 0
        // Now call sendMoney (any target, any value) — this does not affect depositsCount
        // So we can assert the difference directly
        assertTrue(c.depositsCount() != 1, "depositsCount should be 1 in reference, 0 in buggy");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Send ether twice via receive to increment depositsCount by 2 in reference
        vm.deal(address(this), 2 ether);
        payable(address(c)).transfer(1 ether);
        payable(address(c)).transfer(1 ether);
        // Now sendMoney twice (call to self with 0 value, empty data)
        vm.prank(c.owner());
        c.sendMoney(address(this), 0, "");
        vm.prank(c.owner());
        c.sendMoney(address(this), 0, "");
        // Reference: depositsCount = 2 (receive) + 2 (sendMoney) = 4
        // Buggy: depositsCount = 0 (receive) + 2 (sendMoney) = 2
        assertTrue(c.depositsCount() == 4);
    }
}
